INSERT INTO `B7aMf_cky_cookie_categories` VALUES (1,'{\"en\":\"Necessary\",\"it\":\"Necessari\"}','necessary','{\"en\":\"<p>Necessary cookies are required to enable the basic features of this site, such as providing secure log-in or adjusting your consent preferences. These cookies do not store any personally identifiable data.<\\/p>\",\"it\":\"<p>I cookie necessari sono fondamentali per le funzioni di base del sito Web e il sito Web non funzioner\\u00e0 nel modo previsto senza di essi. Questi cookie non memorizzano dati identificativi personali.<\\/p>\"}',1,1,0,1,'[]','0000-00-00 00:00:00','0000-00-00 00:00:00'),(2,'{\"en\":\"Functional\",\"it\":\"Funzionali\"}','functional','{\"en\":\"<p>Functional cookies help perform certain functionalities like sharing the content of the website on social media platforms, collecting feedback, and other third-party features.<\\/p>\",\"it\":\"<p>I cookie funzionali aiutano a svolgere determinate funzionalit\\u00e0 come la condivisione del contenuto del sito Web su piattaforme di social media, la raccolta di feedback e altre funzionalit\\u00e0 di terze parti.<br \\/>Il sito Web dell\\u2019Istituto non utilizza cookies funzionali.<\\/p>\"}',0,1,0,1,'[]','0000-00-00 00:00:00','0000-00-00 00:00:00'),(3,'{\"en\":\"Analytics\",\"it\":\"Analitici\"}','analytics','{\"en\":\"<p>Analytical cookies are used to understand how visitors interact with the website. These cookies help provide information on metrics such as the number of visitors, bounce rate, traffic source, etc.<\\/p>\",\"it\":\"<p>I cookie analitici vengono utilizzati per comprendere come i visitatori interagiscono con il sito Web. Questi cookie aiutano a fornire informazioni sulle metriche di numero di visitatori, frequenza di rimbalzo, fonte di traffico, ecc. Il sito Web dell\\u2019Istituto utilizza esclusivamente gli strumenti statistici anonimizzati messi a disposizione da Web Analytics Italia (Informativa specifica).<\\/p>\"}',0,1,0,1,'[]','0000-00-00 00:00:00','0000-00-00 00:00:00'),(4,'{\"en\":\"Performance\",\"it\":\"Prestazione\"}','performance','{\"en\":\"<p>Performance cookies are used to understand and analyze the key performance indexes of the website which helps in delivering a better user experience for the visitors.<\\/p>\",\"it\":\"<p>I cookie per le prestazioni vengono utilizzati per comprendere e analizzare gli indici di prestazione chiave del sito Web che aiutano a fornire ai visitatori un\'esperienza utente migliore.<\\/p>\"}',0,1,0,1,'[]','0000-00-00 00:00:00','0000-00-00 00:00:00'),(5,'{\"en\":\"Advertisement\",\"it\":\"Pubblicitari\"}','advertisement','{\"en\":\"<p>Advertisement cookies are used to provide visitors with customized advertisements based on the pages you visited previously and to analyze the effectiveness of the ad campaigns.<\\/p>\",\"it\":\"<p>I cookie pubblicitari vengono utilizzati per fornire ai visitatori annunci pubblicitari personalizzati in base alle pagine visitate in precedenza e per analizzare l\'efficacia della campagna pubblicitaria.<br \\/>Il sito Web dell\\u2019Istituto non utilizza cookies pubblicitari.<\\/p>\"}',0,1,0,1,'[]','0000-00-00 00:00:00','0000-00-00 00:00:00');
