INSERT INTO `B7aMf_cky_cookies` VALUES (1,'wordpress_test_cookie','wordpress_test_cookie','{\"en\":\"\",\"it\":\"<p>Verifica che il browser accetti i cookie.<\\/p>\"}','{\"en\":\"1 anno\",\"it\":\"sessione\"}','myp.3dsolution.it',1,'0',0,'','[]','0000-00-00 00:00:00','2023-04-03 09:29:19'),(2,'cookieyes-consent','cookieyes-consent','{\"en\":\"\",\"it\":\"<p>CookieYes imposta questo cookie per ricordare le preferenze di consenso degli utenti in modo che le loro preferenze siano rispettate nelle loro successive visite al sito. Non raccoglie n\\u00e9 memorizza alcuna informazione personale dei visitatori del sito.<\\/p>\"}','{\"en\":\"1 anno\",\"it\":\"1 anno\"}','myp.3dsolution.it',1,'0',0,'','[]','2023-04-03 09:30:45','2023-04-03 09:30:45'),(3,'_lscache_vary','_lscache_vary','{\"en\":\"\",\"it\":\"<p>LiteSpeed Cache \\u2013 accelerazione e ottimizzazione della visualizzazione delle pagine del sito web.<\\/p>\"}','{\"en\":\"2 giorni\",\"it\":\"2 giorni\"}','myp.3dsolution.it',1,'0',0,'','[]','2023-04-03 09:31:38','2023-04-03 09:31:38'),(4,'_pk_id.BmqA4OwpPX.1eab','_pk_id-bmqa4owppx-1eab','{\"en\":\"\",\"it\":\"<p>Web Analytics Italia \\u2013 monitoraggio e statistiche in tempo reale dei visitatori del sito web (memorizza alcuni dettagli sull\\u2019utente come l\\u2019ID visitatore unico).<\\/p>\"}','{\"en\":\"13 mesi\",\"it\":\"13 mesi\"}','myp.3dsolution.it',3,'0',0,'','[]','2023-04-03 09:32:28','2023-04-03 09:32:28'),(5,'_pk_ses.BmqA4OwpPX.1eab','_pk_ses-bmqa4owppx-1eab','{\"en\":\"\",\"it\":\"<p>Web Analytics Italia \\u2013 monitoraggio e statistiche in tempo reale dei visitatori del sito web (memorizzazione temporanea dei dati relativi alla visita).<\\/p>\"}','{\"en\":\"30 minuti\",\"it\":\"30 minuti\"}','myp.3dsolution.it',3,'0',0,'','[]','2023-04-03 09:32:58','2023-04-03 09:32:58');
