lth-check-site-status-result','{\"good\":18,\"recommended\":2,\"critical\":3}','yes'),(531,'recently_activated','a:0:{}','yes'),(540,'cky_cookie_consent_lite_db_version','3.2.5','yes'),(544,'wt_cli_version','3.2.5','yes'),(545,'cky_missing_tables','a:0:{}','yes'),(546,'_transient_cky_banners_transient_prefix','0.56636100 1670413590','yes'),(547,'cky_banner_template','a:1:{s:2:\"it\";a:2:{s:4:\"html\";s:11889:\"<div class=\"cky-overlay cky-hide\"></div><div class=\"cky-btn-revisit-wrapper cky-revisit-hide\" data-cky-tag=\"revisit-consent\" data-tooltip=\"Impostazioni dei cookie\" style=\"background-color:#0056a7\"> <button class=\"cky-btn-revisit\" aria-label=\"Impostazioni dei cookie\"> <img src=\"https://www.dariovettura.it/scuolatest/wp-content/plugins/cookie-law-info/lite/frontend/images/revisit.svg\" alt=\"Revisit consent button\"> </button></div><div class=\"cky-consent-container cky-hide\" tabindex=\"0\"> <div class=\"cky-consent-bar\" data-cky-tag=\"notice\" style=\"background-color:#FFFFFF;border-color:#2a2a2a\"> <button class=\"cky-banner-btn-close\" data-cky-tag=\"close-button\" aria-label=\"Vicino\"> <img src=\"https://www.dariovettura.it/scuolatest/wp-content/plugins/cookie-law-info/lite/frontend/images/close.svg\" alt=\"Close\"> </button> <div class=\"cky-notice\"> <p class=\"cky-title\" role=\"heading\" aria-level=\"1\" data-cky-tag=\"title\" style=\"color:#000000\">Cookies e altri strumenti di tracciamento</p><div class=\"cky-notice-group\"> <div class=\"cky-notice-des\" data-cky-tag=\"description\" style=\"color:#000000\"> <p>Il nostro Istituto non utilizza strumenti di profilazione degli utenti - sono utilizzati esclusivamente cookies tecnici necessari al corretto funzionamento del sito, alla fruibilità dei servizi istituzionali e alla sua accessibilità – sono utilizzati, inoltre, strumenti statistici anonimizzati messi a disposizione da Web Analytics Italia.<br>Per saperne di più sul nostro sito, consulta la ns. Cookie Policy.</p> </div><div class=\"cky-notice-btn-wrapper\" data-cky-tag=\"notice-buttons\"> <button class=\"cky-btn cky-btn-customize\" aria-label=\"Personalizza\" data-cky-tag=\"settings-button\" style=\"color:#000000;background-color:transparent;border-color:#d0d0d0\">Personalizza</button> <button class=\"cky-btn cky-btn-reject\" aria-label=\"Rifiuta tutto\" data-cky-tag=\"reject-button\" style=\"color:#000000;background-color:transparent;border-color:#d0d0d0\">Rifiuta tutto</button> <button class=\"cky-btn cky-btn-accept\" aria-label=\"Accettare tutto\" data-cky-tag=\"accept-button\" style=\"color:#FFFFFF;background-color:#1863dc;border-color:#1863dc\">Accettare tutto</button>  </div></div></div></div></div><div class=\"cky-modal\" tabindex=\"0\"> <div class=\"cky-preference-center\" data-cky-tag=\"detail\" style=\"color:#000000;background-color:#FFFFFF;border-color:#2a2a2a\"> <div class=\"cky-preference-header\"> <span class=\"cky-preference-title\" role=\"heading\" aria-level=\"1\" data-cky-tag=\"detail-title\" style=\"color:#000000\">Personalizza le preferenze di consenso</span> <button class=\"cky-btn-close\" aria-label=\"[cky_preference_close_label]\" data-cky-tag=\"detail-close\"> <img src=\"https://www.dariovettura.it/scuolatest/wp-content/plugins/cookie-law-info/lite/frontend/images/close.svg\" alt=\"Close\"> </button> </div><div class=\"cky-preference-body-wrapper\"> <div class=\"cky-preference-content-wrapper\" data-cky-tag=\"detail-description\" style=\"color:#000000\"> <p>Utilizziamo i cookie per aiutarti a navigare in maniera efficiente e a svolgere determinate funzioni. Troverai informazioni dettagliate su tutti i cookie sotto ogni categoria di consensi sottostanti. I cookie categorizzatati come “Necessari” vengono memorizzati sul tuo browser in quanto essenziali per consentire le funzionalità di base del sito.<br>Non utilizziamo cookie di terze parti.<br>Puoi decidere di attivare o disattivare alcuni o tutti questi cookie, ma la disattivazione di alcuni di questi potrebbe avere un impatto sulla tua esperienza sul browser.</p> </div><div class=\"cky-accordion-wrapper\" data-cky-tag=\"detail-categories\"> <div class=\"cky-accordion\" id=\"ckyDetailCategorynecessary\"> <div class=\"cky-accordion-item\"> <div class=\"cky-accordion-chevron\"><i class=\"cky-chevron-right\"></i></div> <div class=\"cky-accordion-header-wrapper\"> <div class=\"cky-accordion-header\"><button class=\"cky-accordion-btn\" aria-label=\"Necessari\" data-cky-tag=\"detail-category-title\" style=\"color:#000000\">Necessari</button><span class=\"cky-always-active\">Sempre attivi</span> <div class=\"cky-switch\" data-cky-tag=\"detail-category-toggle\"><input type=\"checkbox\" id=\"ckySwitchnecessary\"></div> </div> <div class=\"cky-accordion-header-des\" data-cky-tag=\"detail-category-description\" style=\"color:#000000\"> <p>I cookie necessari sono fondamentali per le funzioni di base del sito Web e il sito Web non funzionerà nel modo previsto senza di essi. Questi cookie non memorizzano dati identificativi personali.</p></div> </div> </div> <div class=\"cky-accordion-body\"> <div class=\"cky-audit-table\" data-cky-tag=\"audit-table\" style=\"color:#d0d0d0;background-color:#2a2a2a;border-color:#474444\"><ul class=\"cky-cookie-des-table\"><li><div>Cookie</div><div>wordpress_test_cookie</div></li><li><div>Durata</div><div>sessione</div></li><li><div>descrizione</div><div><p>Verifica che il browser accetti i cookie.</p></div></li></ul><ul class=\"cky-cookie-des-table\"><li><div>Cookie</div><div>cookieyes-consent</div></li><li><div>Durata</div><div>1 anno</div></li><li><div>descrizione</div><div><p>CookieYes imposta questo cookie per ricordare le preferenze di consenso degli utenti in modo che le loro preferenze siano rispettate nelle loro successive visite al sito. Non raccoglie né memorizza alcuna informazione personale dei visitatori del sito.</p></div></li></ul><ul class=\"cky-cookie-des-table\"><li><div>Cookie</div><div>_lscache_vary</div></li><li><div>Durata</div><div>2 giorni</div></li><li><div>descrizione</div><div><p>LiteSpeed Cache – accelerazione e ottimizzazione della visualizzazione delle pagine del sito web.</p></div></li></ul></div> </div> </div><div class=\"cky-accordion\" id=\"ckyDetailCategoryfunctional\"> <div class=\"cky-accordion-item\"> <div class=\"cky-accordion-chevron\"><i class=\"cky-chevron-right\"></i></div> <div class=\"cky-accordion-header-wrapper\"> <div class=\"cky-accordion-header\"><button class=\"cky-accordion-btn\" aria-label=\"Funzionali\" data-cky-tag=\"detail-category-title\" style=\"color:#000000\">Funzionali</button><span class=\"cky-always-active\">Sempre attivi</span> <div class=\"cky-switch\" data-cky-tag=\"detail-category-toggle\"><input type=\"checkbox\" id=\"ckySwitchfunctional\"></div> </div> <div class=\"cky-accordion-header-des\" data-cky-tag=\"detail-category-description\" style=\"color:#000000\"> <p>I cookie funzionali aiutano a svolgere determinate funzionalità come la condivisione del contenuto del sito Web su piattaforme di social media, la raccolta di feedback e altre funzionalità di terze parti.<br>Il sito Web dell’Istituto non utilizza cookies funzionali.</p></div> </div> </div> <div class=\"cky-accordion-body\"> <div class=\"cky-audit-table\" data-cky-tag=\"audit-table\" style=\"color:#d0d0d0;background-color:#2a2a2a;border-color:#474444\"><p class=\"cky-empty-cookies-text\">Nessun cookie da visualizzare.</p></div> </div> </div><div class=\"cky-accordion\" id=\"ckyDetailCategoryanalytics\"> <div class=\"cky-accordion-item\"> <div class=\"cky-accordion-chevron\"><i class=\"cky-chevron-right\"></i></div> <div class=\"cky-accordion-header-wrapper\"> <div class=\"cky-accordion-header\"><button class=\"cky-accordion-btn\" aria-label=\"Analitici\" data-cky-tag=\"detail-category-title\" style=\"color:#000000\">Analitici</button><span class=\"cky-always-active\">Sempre attivi</span> <div class=\"cky-switch\" data-cky-tag=\"detail-category-toggle\"><input type=\"checkbox\" id=\"ckySwitchanalytics\"></div> </div> <div class=\"cky-accordion-header-des\" data-cky-tag=\"detail-category-description\" style=\"color:#000000\"> <p>I cookie analitici vengono utilizzati per comprendere come i visitatori interagiscono con il sito Web. Questi cookie aiutano a fornire informazioni sulle metriche di numero di visitatori, frequenza di rimbalzo, fonte di traffico, ecc. Il sito Web dell’Istituto utilizza esclusivamente gli strumenti statistici anonimizzati messi a disposizione da Web Analytics Italia (Informativa specifica).</p></div> </div> </div> <div class=\"cky-accordion-body\"> <div class=\"cky-audit-table\" data-cky-tag=\"audit-table\" style=\"color:#d0d0d0;background-color:#2a2a2a;border-color:#474444\"><ul class=\"cky-cookie-des-table\"><li><div>Cookie</div><div>_pk_id.BmqA4OwpPX.1eab</div></li><li><div>Durata</div><div>13 mesi</div></li><li><div>descrizione</div><div><p>Web Analytics Italia – monitoraggio e statistiche in tempo reale dei visitatori del sito web (memorizza alcuni dettagli sull’utente come l’ID visitatore unico).</p></div></li></ul><ul class=\"cky-cookie-des-table\"><li><div>Cookie</div><div>_pk_ses.BmqA4OwpPX.1eab</div></li><li><div>Durata</div><div>30 minuti</div></li><li><div>descrizione</div><div><p>Web Analytics Italia – monitoraggio e statistiche in tempo reale dei visitatori del sito web (memorizzazione temporanea dei dati relativi alla visita).</p></div></li></ul></div> </div> </div><div class=\"cky-accordion\" id=\"ckyDetailCategoryperformance\"> <div class=\"cky-accordion-item\"> <div class=\"cky-accordion-chevron\"><i class=\"cky-chevron-right\"></i></div> <div class=\"cky-accordion-header-wrapper\"> <div class=\"cky-accordion-header\"><button class=\"cky-accordion-btn\" aria-label=\"Prestazione\" data-cky-tag=\"detail-category-title\" style=\"color:#000000\">Prestazione</button><span class=\"cky-always-active\">Sempre attivi</span> <div class=\"cky-switch\" data-cky-tag=\"detail-category-toggle\"><input type=\"checkbox\" id=\"ckySwitchperformance\"></div> </div> <div class=\"cky-accordion-header-des\" data-cky-tag=\"detail-category-description\" style=\"color:#000000\"> <p>I cookie per le prestazioni vengono utilizzati per comprendere e analizzare gli indici di prestazione chiave del sito Web che aiutano a fornire ai visitatori un\'esperienza utente migliore.</p></div> </div> </div> <div class=\"cky-accordion-body\"> <div class=\"cky-audit-table\" data-cky-tag=\"audit-table\" style=\"color:#d0d0d0;background-color:#2a2a2a;border-color:#474444\"><p class=\"cky-empty-cookies-text\">Nessun cookie da visualizzare.</p></div> </div> </div><div class=\"cky-accordion\" id=\"ckyDetailCategoryadvertisement\"> <div class=\"cky-accordion-item\"> <div class=\"cky-accordion-chevron\"><i class=\"cky-chevron-right\"></i></div> <div class=\"cky-accordion-header-wrapper\"> <div class=\"cky-accordion-header\"><button class=\"cky-accordion-btn\" aria-label=\"Pubblicitari\" data-cky-tag=\"detail-category-title\" style=\"color:#000000\">Pubblicitari</button><span class=\"cky-always-active\">Sempre attivi</span> <div class=\"cky-switch\" data-cky-tag=\"detail-category-toggle\"><input type=\"checkbox\" id=\"ckySwitchadvertisement\"></div> </div> <div class=\"cky-accordion-header-des\" data-cky-tag=\"detail-category-description\" style=\"color:#000000\"> <p>I cookie pubblicitari vengono utilizzati per fornire ai visitatori annunci pubblicitari personalizzati in base alle pagine visitate in precedenza e per analizzare l\'efficacia della campagna pubblicitaria.<br>Il sito Web dell’Istituto non utilizza cookies pubblicitari.</p></div> </div> </div> <div class=\"cky-accordion-body\"> <div class=\"cky-audit-table\" data-cky-tag=\"audit-table\" style=\"color:#d0d0d0;background-color:#2a2a2a;border-color:#474444\"><p class=\"cky-empty-cookies-text\">Nessun cookie da visualizzare.</p></div> </div> </div> </div></div><div class=\"cky-footer-wrapper\"> <span class=\"cky-footer-shadow\"></span> <div class=\"cky-prefrence-btn-wrap